using TMPro;
using System; using UnityEngine; using UnityEngine.UI; namespace DungeonSlash { public sealed class ShopItemView : MonoBehaviour { [SerializeField] private Button button; [SerializeField] private TextMeshProUGUI label; public void Configure(Button newButton, TextMeshProUGUI newLabel) { button = newButton; label = newLabel; } public void Bind(EquipmentData item, bool affordable, Action<EquipmentData> buy) { label.text = GameText.Format("ui.shopitemview.79a2a3", item.displayName, item.price, item.description); button.interactable = affordable; button.onClick.RemoveAllListeners(); button.onClick.AddListener(() => buy(item)); } } }
